package com.airesumebuilder.feature.subscription.entity;
import com.airesumebuilder.feature.auth.entity.User; import jakarta.persistence.*; import java.time.Instant; import java.util.*; import lombok.*;
@Entity @Table(name="subscriptions") @Getter @Setter @NoArgsConstructor
public class Subscription { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user; @Column(nullable=false,length=50) private String plan; @Column(nullable=false,length=30) private String status; @Column(name="starts_at",nullable=false) private Instant startsAt; @Column(name="ends_at") private Instant endsAt; @Column(name="is_current",nullable=false) private boolean current=true; @Column(name="current_user_id",insertable=false,updatable=false) private Long currentUserId; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Column(name="updated_at") private Instant updatedAt; @OneToMany(mappedBy="subscription",cascade=CascadeType.ALL,orphanRemoval=true) private List<PaymentTransaction> payments=new ArrayList<>(); @PrePersist void create(){if(createdAt==null)createdAt=Instant.now();} @PreUpdate void update(){updatedAt=Instant.now();} }
